INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, image_url, is_active) VALUES
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'What parameter measures the change in concentration of a reactant or product per unit of time in a chemical reaction?', 'Activation Energy', 'Reaction Rate', 'Equilibrium Constant', 'Reaction Quotient', 'B', 'Reaction rate defines how rapidly reactants are consumed or products are formed over time (e.g., mol/L·s).', 'assets/illustrations/term1/q1.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What parameter measures the change in concentration of a reactant or product per unit of time in a chemical reaction?', 'Activation Energy', 'Reaction Rate', 'Equilibrium Constant', 'Reaction Quotient', 'B', 'Reaction rate defines how rapidly reactants are consumed or products are formed over time (e.g., mol/L·s).', 'assets/illustrations/term1/q1.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Identify the thermodynamic factor that elevates reaction rates by increasing the average kinetic energy and velocity of colliding reactant particles.', 'Temperature', 'Surface Area', 'Molecular Volume', 'Atmospheric Humidity', 'A', 'Raising temperature provides particles with greater kinetic energy, increasing collision frequency and energy threshold compliance.', 'assets/illustrations/term1/q2.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Identify the thermodynamic factor that elevates reaction rates by increasing the average kinetic energy and velocity of colliding reactant particles.', 'Temperature', 'Surface Area', 'Molecular Volume', 'Atmospheric Humidity', 'A', 'Raising temperature provides particles with greater kinetic energy, increasing collision frequency and energy threshold compliance.', 'assets/illustrations/term1/q2.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'What chemical agent accelerates a reaction by offering an alternative pathway with a lower activation energy while remaining unconsumed at the end?', 'Inhibitor', 'Solvent', 'Catalyst', 'Precipitate', 'C', 'Catalysts provide lower-energy transition states without altering reaction thermodynamics or being permanently consumed.', 'assets/illustrations/term1/q3.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What chemical agent accelerates a reaction by offering an alternative pathway with a lower activation energy while remaining unconsumed at the end?', 'Inhibitor', 'Solvent', 'Catalyst', 'Precipitate', 'C', 'Catalysts provide lower-energy transition states without altering reaction thermodynamics or being permanently consumed.', 'assets/illustrations/term1/q3.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'What term describes a chemical process in which the potential energy of reactants is greater than products, releasing enthalpy into the surroundings?', 'Endothermic Reaction', 'Exothermic Reaction', 'Photolytic Cleavage', 'Neutralization Inversion', 'B', 'Exothermic reactions release net heat energy (negative ΔH) as bond-forming releases more energy than bond-breaking consumes.', 'assets/illustrations/term1/q4.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What term describes a chemical process in which the potential energy of reactants is greater than products, releasing enthalpy into the surroundings?', 'Endothermic Reaction', 'Exothermic Reaction', 'Photolytic Cleavage', 'Neutralization Inversion', 'B', 'Exothermic reactions release net heat energy (negative ΔH) as bond-forming releases more energy than bond-breaking consumes.', 'assets/illustrations/term1/q4.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Identify the classification of a chemical transformation that requires continuous thermal energy absorption from its ambient surroundings (+ΔH).', 'Exothermic Reaction', 'Endothermic Reaction', 'Pyrolysis Detonation', 'Condensation Reaction', 'B', 'Endothermic processes absorb heat because breaking bonds requires more energy than is evolved during product formation.', 'assets/illustrations/term1/q5.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Identify the classification of a chemical transformation that requires continuous thermal energy absorption from its ambient surroundings (+ΔH).', 'Exothermic Reaction', 'Endothermic Reaction', 'Pyrolysis Detonation', 'Condensation Reaction', 'B', 'Endothermic processes absorb heat because breaking bonds requires more energy than is evolved during product formation.', 'assets/illustrations/term1/q5.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'When a solid reactant block is pulverized into a fine powder, what specific physical dimension expands to yield more contact sites for collisions?', 'Density', 'Molecular Mass', 'Surface Area', 'Nuclear Charge', 'C', 'Subdividing solids increases exposed surface area, allowing more reactant particles to collide simultaneously.', 'assets/illustrations/term1/q6.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'When a solid reactant block is pulverized into a fine powder, what specific physical dimension expands to yield more contact sites for collisions?', 'Density', 'Molecular Mass', 'Surface Area', 'Nuclear Charge', 'C', 'Subdividing solids increases exposed surface area, allowing more reactant particles to collide simultaneously.', 'assets/illustrations/term1/q6.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'What term designates the essential triad model consisting of fuel, an oxidizing agent (oxygen), and ignition heat necessary for sustained combustion?', 'Fire Triangle', 'Triple Point', 'Phase Diagram', 'Arrhenius Triad', 'A', 'Removing any one component of the fire triangle (fuel, oxidizer, or heat) starves and extinguishes a combustion reaction.', 'assets/illustrations/term1/q7.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What term designates the essential triad model consisting of fuel, an oxidizing agent (oxygen), and ignition heat necessary for sustained combustion?', 'Fire Triangle', 'Triple Point', 'Phase Diagram', 'Arrhenius Triad', 'A', 'Removing any one component of the fire triangle (fuel, oxidizer, or heat) starves and extinguishes a combustion reaction.', 'assets/illustrations/term1/q7.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'What specific kinetic factor is altered in cold storage to reduce enzymatic degradation and bacterial decay rates in perishable food?', 'Increased Acidity', 'Lower Temperature', 'Higher Pressure', 'Decreased Surface Area', 'B', 'Cold environments diminish molecular kinetic energy, significantly reducing collision frequency and biochemical reaction rates.', 'assets/illustrations/term1/q8.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What specific kinetic factor is altered in cold storage to reduce enzymatic degradation and bacterial decay rates in perishable food?', 'Increased Acidity', 'Lower Temperature', 'Higher Pressure', 'Decreased Surface Area', 'B', 'Cold environments diminish molecular kinetic energy, significantly reducing collision frequency and biochemical reaction rates.', 'assets/illustrations/term1/q8.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'What chemical compound acts to decrease the velocity of a chemical reaction or deactivate catalytic function when introduced into a system?', 'Promoter', 'Enzyme', 'Inhibitor', 'Activator', 'C', 'Inhibitors interfere with active sites or reactive intermediates, raising activation energy or blocking effective collisions.', 'assets/illustrations/term1/q9.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What chemical compound acts to decrease the velocity of a chemical reaction or deactivate catalytic function when introduced into a system?', 'Promoter', 'Enzyme', 'Inhibitor', 'Activator', 'C', 'Inhibitors interfere with active sites or reactive intermediates, raising activation energy or blocking effective collisions.', 'assets/illustrations/term1/q9.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Identify the classic, highly exothermic oxidation reaction exhibited when hydrocarbon materials such as wood or natural gas undergo rapid burning in air.', 'Photosynthesis', 'Electrolysis', 'Combustion', 'Polymerization', 'C', 'Combustion is a canonical exothermic oxidation reaction releasing heat, light, and gaseous products (CO₂ and H₂O).', 'assets/illustrations/term1/q10.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Identify the classic, highly exothermic oxidation reaction exhibited when hydrocarbon materials such as wood or natural gas undergo rapid burning in air.', 'Photosynthesis', 'Electrolysis', 'Combustion', 'Polymerization', 'C', 'Combustion is a canonical exothermic oxidation reaction releasing heat, light, and gaseous products (CO₂ and H₂O).', 'assets/illustrations/term1/q10.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'What standard kinetic parameter (Ea) represents the minimum energy barrier colliding molecules must overcome to transition into products?', 'Enthalpy of Formation', 'Activation Energy', 'Gibbs Free Energy', 'Lattice Energy', 'B', 'Activation energy (Ea) is the minimum kinetic energy needed to break initial bonds and form an activated complex during a collision.', 'assets/illustrations/term1/q11.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What standard kinetic parameter (Ea) represents the minimum energy barrier colliding molecules must overcome to transition into products?', 'Enthalpy of Formation', 'Activation Energy', 'Gibbs Free Energy', 'Lattice Energy', 'B', 'Activation energy (Ea) is the minimum kinetic energy needed to break initial bonds and form an activated complex during a collision.', 'assets/illustrations/term1/q11.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'What foundational theory posits that chemical reaction rates depend on collision frequency, sufficient kinetic energy, and proper molecular orientation?', 'Collision Theory', 'Dalton''s Atomic Theory', 'VSEPR Theory', 'Le Chatelier''s Principle', 'A', 'Collision theory states that reactions occur only when particles collide with sufficient energy (E >= Ea) and favorable spatial orientation.', 'assets/illustrations/term1/q12.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What foundational theory posits that chemical reaction rates depend on collision frequency, sufficient kinetic energy, and proper molecular orientation?', 'Collision Theory', 'Dalton''s Atomic Theory', 'VSEPR Theory', 'Le Chatelier''s Principle', 'A', 'Collision theory states that reactions occur only when particles collide with sufficient energy (E >= Ea) and favorable spatial orientation.', 'assets/illustrations/term1/q12.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Evaluating a reaction system, what overall kinetic impact occurs to the reaction rate when a solid reactant is mechanically crushed into smaller granules?', 'Slows the Reaction Rate', 'Has No Effect on the Rate', 'Increases the Reaction Rate', 'Reverses the Chemical Reaction', 'C', 'Crushing increases available surface area, thereby increasing collision frequency between solid and fluid reactants.', 'assets/illustrations/term1/q13.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Evaluating a reaction system, what overall kinetic impact occurs to the reaction rate when a solid reactant is mechanically crushed into smaller granules?', 'Slows the Reaction Rate', 'Has No Effect on the Rate', 'Increases the Reaction Rate', 'Reverses the Chemical Reaction', 'C', 'Crushing increases available surface area, thereby increasing collision frequency between solid and fluid reactants.', 'assets/illustrations/term1/q13.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'What general effect does reducing system temperature have on the overall velocity and collision energy distribution of chemical reactions?', 'Accelerates the Reaction Rate', 'Slows the Reaction Rate', 'Triples the Reaction Rate', 'Shifts the Reaction to Explosive Detonation', 'B', 'Lowering temperature reduces particle velocity and reduces the fraction of molecules possessing E >= Ea, slowing reaction velocity.', 'assets/illustrations/term1/q14.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What general effect does reducing system temperature have on the overall velocity and collision energy distribution of chemical reactions?', 'Accelerates the Reaction Rate', 'Slows the Reaction Rate', 'Triples the Reaction Rate', 'Shifts the Reaction to Explosive Detonation', 'B', 'Lowering temperature reduces particle velocity and reduces the fraction of molecules possessing E >= Ea, slowing reaction velocity.', 'assets/illustrations/term1/q14.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Powdered calcium carbonate reacts much faster with hydrochloric acid than solid marble chips. Identify the physical variable responsible for this rate disparity.', 'Surface Area', 'Chemical Composition', 'Molar Mass', 'Atmospheric Pressure', 'A', 'Powdered forms expose vastly more surface area per unit mass, providing more active sites for acid-carbonate collisions.', 'assets/illustrations/term1/q15.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Powdered calcium carbonate reacts much faster with hydrochloric acid than solid marble chips. Identify the physical variable responsible for this rate disparity.', 'Surface Area', 'Chemical Composition', 'Molar Mass', 'Atmospheric Pressure', 'A', 'Powdered forms expose vastly more surface area per unit mass, providing more active sites for acid-carbonate collisions.', 'assets/illustrations/term1/q15.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Concentrated hydrochloric acid reacts more vigorously than dilute acid. What solution-state property accounts for this higher reaction rate?', 'Viscosity', 'Concentration', 'Surface Tension', 'Color Intensity', 'B', 'Higher solute concentration increases solute particle density, leading to more frequent molecular collisions per unit time.', 'assets/illustrations/term1/q16.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Concentrated hydrochloric acid reacts more vigorously than dilute acid. What solution-state property accounts for this higher reaction rate?', 'Viscosity', 'Concentration', 'Surface Tension', 'Color Intensity', 'B', 'Higher solute concentration increases solute particle density, leading to more frequent molecular collisions per unit time.', 'assets/illustrations/term1/q16.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'What specific terms designate specialized protein molecules that serve as organic catalysts regulating metabolic pathways in living cells?', 'Lipids', 'Hormones', 'Enzymes', 'Polysaccharides', 'C', 'Enzymes are biological catalysts that lower activation energy for vital biochemical reactions inside living organisms.', 'assets/illustrations/term1/q17.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What specific terms designate specialized protein molecules that serve as organic catalysts regulating metabolic pathways in living cells?', 'Lipids', 'Hormones', 'Enzymes', 'Polysaccharides', 'C', 'Enzymes are biological catalysts that lower activation energy for vital biochemical reactions inside living organisms.', 'assets/illustrations/term1/q17.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'When applying water to extinguish a structural fire, which primary component of the fire triangle is removed due to water''s high specific heat capacity?', 'Fuel', 'Oxygen', 'Heat', 'Light Radiation', 'C', 'Water absorbs substantial thermal energy during vaporization, rapidly cooling the fuel below its ignition temperature.', 'assets/illustrations/term1/q18.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'When applying water to extinguish a structural fire, which primary component of the fire triangle is removed due to water''s high specific heat capacity?', 'Fuel', 'Oxygen', 'Heat', 'Light Radiation', 'C', 'Water absorbs substantial thermal energy during vaporization, rapidly cooling the fuel below its ignition temperature.', 'assets/illustrations/term1/q18.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Deploying a dense fire blanket over a grease spill smothers the flame. Which constituent of the combustion triad is isolated by this physical barrier?', 'Oxygen', 'Fuel', 'Heat', 'Carbon Monoxide', 'A', 'A fire blanket smothers flames by sealing off atmospheric oxygen gas (O₂), halting the chemical reaction.', 'assets/illustrations/term1/q19.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Deploying a dense fire blanket over a grease spill smothers the flame. Which constituent of the combustion triad is isolated by this physical barrier?', 'Oxygen', 'Fuel', 'Heat', 'Carbon Monoxide', 'A', 'A fire blanket smothers flames by sealing off atmospheric oxygen gas (O₂), halting the chemical reaction.', 'assets/illustrations/term1/q19.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Coating iron structures with paint or zinc layers protects against rusting by physically preventing contact with which two environmental agents?', 'Nitrogen and Carbon Dioxide', 'Oxygen and Water (Moisture)', 'Hydrogen and Methane', 'Sulfur Dioxide and Argon', 'B', 'Corrosion requires both oxygen gas and moisture (H₂O) to facilitate the electrochemical oxidation of elemental iron to rust (Fe₂O₃·nH₂O).', 'assets/illustrations/term1/q20.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Coating iron structures with paint or zinc layers protects against rusting by physically preventing contact with which two environmental agents?', 'Nitrogen and Carbon Dioxide', 'Oxygen and Water (Moisture)', 'Hydrogen and Methane', 'Sulfur Dioxide and Argon', 'B', 'Corrosion requires both oxygen gas and moisture (H₂O) to facilitate the electrochemical oxidation of elemental iron to rust (Fe₂O₃·nH₂O).', 'assets/illustrations/term1/q20.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'What ancient food preservation technique inhibits bacterial metabolism by removing the aqueous solvent necessary for cellular enzymatic reactions?', 'Boiling', 'Fermentation', 'Drying, Salting, or Sugaring', 'Pasteurized Homogenization', 'C', 'Removing water creates a hypertonic or desiccated environment that halts microbial enzymatic reactions and retards food spoilage.', 'assets/illustrations/term1/q21.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What ancient food preservation technique inhibits bacterial metabolism by removing the aqueous solvent necessary for cellular enzymatic reactions?', 'Boiling', 'Fermentation', 'Drying, Salting, or Sugaring', 'Pasteurized Homogenization', 'C', 'Removing water creates a hypertonic or desiccated environment that halts microbial enzymatic reactions and retards food spoilage.', 'assets/illustrations/term1/q21.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Identify the industrial preservation process that uses high-temperature thermal sterilization to denature enzymes followed by airtight sealing to exclude oxygen.', 'Canning', 'Freeze-drying', 'Pickling', 'Salting', 'A', 'Canning denatures destructive microorganisms/enzymes with heat and creates an anaerobic seal preventing recontamination.', 'assets/illustrations/term1/q22.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Identify the industrial preservation process that uses high-temperature thermal sterilization to denature enzymes followed by airtight sealing to exclude oxygen.', 'Canning', 'Freeze-drying', 'Pickling', 'Salting', 'A', 'Canning denatures destructive microorganisms/enzymes with heat and creates an anaerobic seal preventing recontamination.', 'assets/illustrations/term1/q22.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'What physical effect does mechanical stirring or agitation have on the rate of reaction between liquid reactants or dissolved solutes?', 'Slows the Reaction Rate', 'Speeds up the Reaction Rate', 'Prevents Molecular Contact', 'Destroys the Reactant Molecules', 'B', 'Agitation distributes reactant particles uniformly, preventing local concentration depletion and promoting frequent collisions.', 'assets/illustrations/term1/q23.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What physical effect does mechanical stirring or agitation have on the rate of reaction between liquid reactants or dissolved solutes?', 'Slows the Reaction Rate', 'Speeds up the Reaction Rate', 'Prevents Molecular Contact', 'Destroys the Reactant Molecules', 'B', 'Agitation distributes reactant particles uniformly, preventing local concentration depletion and promoting frequent collisions.', 'assets/illustrations/term1/q23.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Identify the endothermic biological process in plants that continuously absorbs solar radiant energy to convert carbon dioxide and water into glucose.', 'Cellular Respiration', 'Transpiration', 'Photosynthesis', 'Glycolysis', 'C', 'Photosynthesis is driven by light energy absorption, converting low-energy reactants (CO₂, H₂O) into high-energy carbohydrates.', 'assets/illustrations/term1/q24.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Identify the endothermic biological process in plants that continuously absorbs solar radiant energy to convert carbon dioxide and water into glucose.', 'Cellular Respiration', 'Transpiration', 'Photosynthesis', 'Glycolysis', 'C', 'Photosynthesis is driven by light energy absorption, converting low-energy reactants (CO₂, H₂O) into high-energy carbohydrates.', 'assets/illustrations/term1/q24.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Analytically describe the principal kinetic mechanism by which a catalyst increases the rate of a chemical transformation.', 'By Increasing System Temperature', 'By Lowering the Activation Energy', 'By Increasing Reactant Enthalpy', 'By Raising the Enthalpy of Products', 'B', 'Catalysts provide an alternate mechanism with a lower activation energy barrier (Ea), allowing a larger fraction of collisions to yield products.', 'assets/illustrations/term1/q25.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Analytically describe the principal kinetic mechanism by which a catalyst increases the rate of a chemical transformation.', 'By Increasing System Temperature', 'By Lowering the Activation Energy', 'By Increasing Reactant Enthalpy', 'By Raising the Enthalpy of Products', 'B', 'Catalysts provide an alternate mechanism with a lower activation energy barrier (Ea), allowing a larger fraction of collisions to yield products.', 'assets/illustrations/term1/q25.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'From a molecular dynamics perspective, why does elevated temperature produce a dramatic exponential increase in chemical reaction rates?', 'Particles Become Heavier and Denser', 'Bonds Weaken Spontaneously Without Collision', 'More Frequent Collisions and More Particles Exceed Ea', 'The Volume of Molecules Expands Tenfold', 'C', 'Higher temperature shifts the energy distribution rightward, vastly expanding the population of particles possessing E >= Ea.', 'assets/illustrations/term1/q26.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'From a molecular dynamics perspective, why does elevated temperature produce a dramatic exponential increase in chemical reaction rates?', 'Particles Become Heavier and Denser', 'Bonds Weaken Spontaneously Without Collision', 'More Frequent Collisions and More Particles Exceed Ea', 'The Volume of Molecules Expands Tenfold', 'C', 'Higher temperature shifts the energy distribution rightward, vastly expanding the population of particles possessing E >= Ea.', 'assets/illustrations/term1/q26.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'What kinetic conditions cause chemical detonations and explosions to proceed within microseconds compared to routine combustion?', 'Instant Gas Release, High Heat, and Large Surface Contact', 'Low Pressure, Cold Temperatures, and Slow Diffusion', 'Airtight Oxygen Depletion and Moisture', 'Zero Activation Energy and High Latent Freezing', 'A', 'Explosions involve rapid chain reactions generating extreme thermal energy and expanding gases almost instantaneously.', 'assets/illustrations/term1/q27.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What kinetic conditions cause chemical detonations and explosions to proceed within microseconds compared to routine combustion?', 'Instant Gas Release, High Heat, and Large Surface Contact', 'Low Pressure, Cold Temperatures, and Slow Diffusion', 'Airtight Oxygen Depletion and Moisture', 'Zero Activation Energy and High Latent Freezing', 'A', 'Explosions involve rapid chain reactions generating extreme thermal energy and expanding gases almost instantaneously.', 'assets/illustrations/term1/q27.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Why does the rate of a chemical reaction gradually decay over time and eventually drop to zero as the process reaches completion?', 'Activation Energy Increases Continuously', 'Reactants are Consumed, Stopping Effective Collisions', 'Catalysts Evaporate Out of the System', 'The Solution Freezes Solid Spontaneously', 'B', 'As reactants turn into products, reactant concentration drops to zero, terminating effective molecular collisions.', 'assets/illustrations/term1/q28.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Why does the rate of a chemical reaction gradually decay over time and eventually drop to zero as the process reaches completion?', 'Activation Energy Increases Continuously', 'Reactants are Consumed, Stopping Effective Collisions', 'Catalysts Evaporate Out of the System', 'The Solution Freezes Solid Spontaneously', 'B', 'As reactants turn into products, reactant concentration drops to zero, terminating effective molecular collisions.', 'assets/illustrations/term1/q28.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Designate the vehicle emissions control device that utilizes platinum, palladium, and rhodium surface catalysts to accelerate toxic gas conversion.', 'Muffler Chamber', 'Turbocharger Turbine', 'Catalytic Converter', 'Radiator Heat Exchanger', 'C', 'Catalytic converters convert pollutants (CO, NOx, unburnt hydrocarbons) into safer gases (CO₂, N₂, H₂O) via surface catalysis.', 'assets/illustrations/term1/q29.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Designate the vehicle emissions control device that utilizes platinum, palladium, and rhodium surface catalysts to accelerate toxic gas conversion.', 'Muffler Chamber', 'Turbocharger Turbine', 'Catalytic Converter', 'Radiator Heat Exchanger', 'C', 'Catalytic converters convert pollutants (CO, NOx, unburnt hydrocarbons) into safer gases (CO₂, N₂, H₂O) via surface catalysis.', 'assets/illustrations/term1/q29.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Fanning smoldering embers or introducing pure oxygen accelerates combustion rapidly. Identify the specific kinetic factor being manipulated.', 'Concentration of Oxygen', 'Surface Area of Wood', 'Inherent Bond Polarity', 'Gravitational Pull', 'A', 'Elevating gaseous O₂ partial pressure increases the collision frequency between oxygen molecules and fuel particles.', 'assets/illustrations/term1/q30.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Fanning smoldering embers or introducing pure oxygen accelerates combustion rapidly. Identify the specific kinetic factor being manipulated.', 'Concentration of Oxygen', 'Surface Area of Wood', 'Inherent Bond Polarity', 'Gravitational Pull', 'A', 'Elevating gaseous O₂ partial pressure increases the collision frequency between oxygen molecules and fuel particles.', 'assets/illustrations/term1/q30.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'In heterogeneous reactions involving different physical states (e.g., solid-liquid), what specific spatial boundary controls the maximum reaction rate?', 'Interior Atomic Nucleus', 'Phase Boundary / Interfacial Surface Area', 'Glass Container Thickness', 'Planetary Magnetic Field', 'B', 'Heterogeneous reactions occur exclusively at the phase boundary; increasing interfacial contact area accelerates reaction velocity.', 'assets/illustrations/term1/q31.svg', true),
