('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Compressing a gaseous reaction mixture into a smaller volume accelerates the reaction rate. What primary factor causes this acceleration?', 'Decreased Temperature', 'Increased Activation Energy', 'Increased Gas Concentration / Partial Pressure', 'Lower Molecular Mass', 'C', 'Decreasing container volume increases gas concentration (molecules per unit volume), raising collision frequency.', 'assets/illustrations/term1/q32.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Compressing a gaseous reaction mixture into a smaller volume accelerates the reaction rate. What primary factor causes this acceleration?', 'Decreased Temperature', 'Increased Activation Energy', 'Increased Gas Concentration / Partial Pressure', 'Lower Molecular Mass', 'C', 'Decreasing container volume increases gas concentration (molecules per unit volume), raising collision frequency.', 'assets/illustrations/term1/q32.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'What unstable, high-energy arrangement of atoms exists fleetingly at the peak of the activation energy barrier during a collision?', 'Stable Reactant Molecule', 'Activated Complex (Transition State)', 'Neutral Salt Precipitate', 'Catalyst Inhibitor Complex', 'B', 'The activated complex is the short-lived configuration at maximum potential energy where old bonds break and new bonds form.', 'assets/illustrations/term1/q33.svg', true),
