('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'What category of chemical reactions relies on the absorption of light quanta (photons) to overcome activation energy barriers?', 'Photochemical Reactions', 'Electrochemical Reactions', 'Thermonuclear Fusion', 'Hydrothermal Precipitation', 'A', 'Photochemical reactions absorb electromagnetic radiation (UV/visible light) to excite molecules to reactive states.', 'assets/illustrations/term1/q34.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'What category of chemical reactions relies on the absorption of light quanta (photons) to overcome activation energy barriers?', 'Photochemical Reactions', 'Electrochemical Reactions', 'Thermonuclear Fusion', 'Hydrothermal Precipitation', 'A', 'Photochemical reactions absorb electromagnetic radiation (UV/visible light) to excite molecules to reactive states.', 'assets/illustrations/term1/q34.svg', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Why does biological enzymatic reaction rate sharply collapse to zero when temperature exceeds an organism''s optimal threshold?', 'Substrate Over-saturation', 'Freezing of Cytoplasm', 'Enzyme Denaturation', 'Excess Water Vaporization', 'C', 'Excessive heat disrupts tertiary enzyme protein structure (denaturation), destroying the catalytic active site.', 'assets/illustrations/term1/q35.svg', true),
